package com.obysoft.faithOS.service;
import java.time.LocalDateTime;import org.springframework.beans.factory.annotation.Value;import org.springframework.boot.ApplicationArguments;import org.springframework.boot.ApplicationRunner;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import com.obysoft.faithOS.repository.*;
@Service public class SensitiveDataMaintenanceService implements ApplicationRunner{private final UserRepository users;private final AbsenceMotivationRepository absences;private final MemberMessageRepository messages;private final SensitiveDataService crypto;private final int absenceDays,messageDays;public SensitiveDataMaintenanceService(UserRepository u,AbsenceMotivationRepository a,MemberMessageRepository m,SensitiveDataService c,@Value("${app.retention.absence-days:365}")int ad,@Value("${app.retention.message-days:730}")int md){users=u;absences=a;messages=m;crypto=c;absenceDays=ad;messageDays=md;}
 @Override @Transactional public void run(ApplicationArguments args){users.findAll().forEach(u->{String cpf=crypto.decrypt(u.getCpf());u.setCpf(crypto.encrypt(cpf));u.setCpfHash(crypto.hash(cpf));u.setEmergencyContactName(crypto.encrypt(crypto.decrypt(u.getEmergencyContactName())));u.setEmergencyContactPhone(crypto.encrypt(crypto.decrypt(u.getEmergencyContactPhone())));});absences.findAll().forEach(a->{a.setReason(crypto.encrypt(crypto.decrypt(a.getReason())));if(a.getExpiresAt()==null)a.setExpiresAt(a.getCreatedAt().plusDays(absenceDays));});messages.findAll().forEach(m->{m.setMessage(crypto.encrypt(crypto.decrypt(m.getMessage())));m.setAttachmentData(crypto.encrypt(crypto.decrypt(m.getAttachmentData())));if(m.getExpiresAt()==null)m.setExpiresAt(m.getCreatedAt().plusDays(messageDays));});}
 @Scheduled(cron="0 20 3 * * *")@Transactional public void purgeExpired(){LocalDateTime now=LocalDateTime.now();messages.deleteByExpiresAtBefore(now);absences.deleteByExpiresAtBefore(now);}}
